"""Two-phase A2A server startup for ``rasa run``.

Routes, bearer auth, and a placeholder card are bound before the model loads,
from the config source the project layout selects. A2A is fully started only
once the model has loaded and :func:`bind_a2a_server_to_loaded_model` has
confirmed the loaded engine matches that source and installed the executor.
A later ``PUT /model`` or ``DELETE /model`` goes through
:func:`rebind_a2a_server_to_swapped_model`, which points later turns at the
swapped model, rebuilds the published agent card, and returns the in-flight
turns that must finish before the retired agent is closed.
"""

from __future__ import annotations

import asyncio
from pathlib import Path
from typing import TYPE_CHECKING, Optional, Union

from pydantic import BaseModel, ConfigDict

from rasa.core.a2a_server.config import A2AServerSettings
from rasa.core.a2a_server.config_sources import (
    resolve_agent_card_against_project,
    resolved_a2a_project_root,
    select_a2a_config_source,
    validate_a2a_server_engine_or_raise,
    warn_if_other_engine_declares_a2a_server,
)
from rasa.shared.engine_version import (
    MANTLE_ENGINE_VERSION,
    ModelPathArg,
    resolve_engine_version_for_cli,
)
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from sanic import Sanic

    from rasa.core.a2a_server.engine_adapter import A2AEngineAdapter
    from rasa.core.agent import Agent
    from rasa.core.config.available_endpoints import AvailableEndpoints


class A2ACardBind(BaseModel):
    """Listen address a published AgentCard was built against."""

    model_config = ConfigDict(frozen=True)

    port: int | None = None
    interface: str | None = None
    scheme: str | None = None


class A2AServerStartup(BaseModel):
    """Engine-neutral settings bound before the model loads.

    Options that only one engine understands are not fields here. CALM adds
    them on :class:`CalmA2AServerStartup`; Mantle adds them on its own startup
    type, next to the Mantle config.
    """

    model_config = ConfigDict(frozen=True)

    engine_version: str
    settings: A2AServerSettings

    def agent_card_settings(self) -> A2AServerSettings:
        """Settings the generated AgentCard is built from.

        An engine overrides this when its card must not advertise a capability
        the server cannot serve yet; routes and auth still use ``settings``.
        """
        return self.settings


class CalmA2AServerStartup(A2AServerStartup):
    """CALM binding. Repair patterns are a CALM card and task-state option."""

    include_conversation_repair: bool = True


def resolve_a2a_server_startup(
    *,
    endpoints: Optional["AvailableEndpoints"],
    project_root: Union[str, Path, None] = None,
    model_path: ModelPathArg = None,
) -> Optional[A2AServerStartup]:
    """Resolve A2A settings from the engine the project layout implies.

    The model is not loaded yet, so the engine comes from
    :func:`~rasa.shared.engine_version.resolve_engine_version_for_cli`. The
    loaded model is checked against this choice in
    :func:`bind_a2a_server_to_loaded_model`.

    Returns:
        The startup binding, or ``None`` when A2A is not enabled for that engine.
    """
    root = resolved_a2a_project_root(project_root)
    engine_version = resolve_engine_version_for_cli(
        project_root=root, model_path=model_path
    )
    source = select_a2a_config_source(
        engine_version, endpoints=endpoints, project_root=root
    )
    settings = resolve_agent_card_against_project(source.load(), root)
    warn_if_other_engine_declares_a2a_server(
        engine_version, endpoints=endpoints, project_root=root
    )
    if settings is None:
        return None
    return source.to_startup(settings)


async def bind_a2a_server_to_loaded_model(
    app: "Sanic",
    startup: A2AServerStartup,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> None:
    """Finish A2A startup once ``app.ctx.agent`` has a loaded model.

    Fails with ``validation.a2a_server.engine_mismatch`` when the loaded model
    runs on another engine than the one the settings were read for, and with
    ``validation.a2a_server.incompatible_session_config`` when those bound
    settings disagree with the processor session config. This is the only
    session check on the ``rasa run`` path; ``load_agent`` skips its own
    re-parse there so the check runs against the file that was bound.
    Otherwise resolves the runtime agent card from the engine adapter (CALM
    flows, or the Mantle skill catalog) and keeps *startup* on
    ``app.ctx.a2a_startup``. Both engines then install the shared executor.
    Task state, status, and cancel go through the engine adapter.
    """
    from rasa.core.a2a_server.bootstrap import resolve_a2a_agent_card_at_startup
    from rasa.core.a2a_server.sanic_app import set_a2a_agent_card_ctx

    agent = app.ctx.agent
    processor = agent.processor
    if processor is None:
        raise RasaException("Cannot start the A2A server: agent model is not loaded.")

    settings = startup.settings
    engine_adapter = _validated_engine_adapter(agent, startup)
    app.ctx.a2a_startup = startup

    # Checked here, not only in the factory, so a substituted adapter cannot
    # skip it. Mantle has its own startup type and is checked by the factory.
    if processor.engine_version != MANTLE_ENGINE_VERSION and not isinstance(
        startup, CalmA2AServerStartup
    ):
        raise RasaException(
            "Cannot start the A2A server: the loaded CALM model has no CALM "
            "A2A startup binding."
        )

    runtime_agent_card = await resolve_a2a_agent_card_at_startup(
        agent,
        startup.agent_card_settings(),
        engine_adapter,
        port=port,
        interface=interface,
        scheme=scheme,
    )
    set_a2a_agent_card_ctx(app, runtime_agent_card)
    app.ctx.a2a_card_bind = A2ACardBind(port=port, interface=interface, scheme=scheme)

    from rasa.core.a2a_server.rasa_a2a_agent_executor import RasaA2AAgentExecutor

    executor = RasaA2AAgentExecutor(
        agent,
        engine_adapter=engine_adapter,
        task_timeout_seconds=settings.effective_task_timeout_seconds(),
        message_cache_ttl_seconds=settings.effective_message_cache_ttl_seconds(),
        max_contexts=settings.effective_max_contexts(),
        a2a_server_config=settings,
        agent_card=runtime_agent_card,
    )
    app.ctx.a2a_agent_executor = executor
    app.ctx.a2a_request_handler = executor.request_handler


async def rebind_a2a_server_to_swapped_model(
    app: "Sanic", agent: "Agent"
) -> list[asyncio.Event]:
    """Point a bound A2A server at the model ``PUT /model`` is about to install.

    No-op when A2A was never bound. Otherwise the swapped model is checked the
    same way as at startup (engine match, session config), the published agent
    card is rebuilt from that model, and a fresh adapter replaces the one the
    executor holds. A turn already in ``execute()`` keeps the agent it
    registered with. The returned events are set when those turns finish; the
    caller closes the retired agent only after that. An unloaded model
    (``DELETE /model``, no processor) skips the startup checks, rebinds to
    that empty agent, and publishes a card with no generated skills.

    A static ``agent_card_path`` still wins over the generated card.

    Raises:
        ValidationError: when the swapped model fails the startup checks. The
            caller keeps the current agent in that case.
        RasaException: when the agent card cannot be rebuilt, for example a
            missing ``agent_card_path`` or flows the CALM adapter cannot load.
            The caller keeps the current agent in that case too.
    """
    startup = getattr(app.ctx, "a2a_startup", None)
    if startup is None:
        return []

    from rasa.core.a2a_server.bootstrap import (
        agent_card_without_loaded_model,
        resolve_a2a_agent_card_at_startup,
    )
    from rasa.core.a2a_server.engine_adapter import (
        build_a2a_engine_adapter_for_startup,
    )
    from rasa.core.a2a_server.sanic_app import set_a2a_agent_card_ctx

    stored_bind = getattr(app.ctx, "a2a_card_bind", None)
    bind = stored_bind if isinstance(stored_bind, A2ACardBind) else A2ACardBind()
    port = bind.port
    interface = bind.interface
    scheme = bind.scheme
    card_settings = startup.agent_card_settings()

    if agent.processor is None:
        engine_adapter = build_a2a_engine_adapter_for_startup(agent, startup)
        runtime_agent_card = agent_card_without_loaded_model(
            card_settings,
            port=port,
            interface=interface,
            scheme=scheme,
        )
    else:
        engine_adapter = _validated_engine_adapter(agent, startup)
        runtime_agent_card = await resolve_a2a_agent_card_at_startup(
            agent,
            card_settings,
            engine_adapter,
            port=port,
            interface=interface,
            scheme=scheme,
        )

    executor = getattr(app.ctx, "a2a_agent_executor", None)
    pending: list[asyncio.Event] = []
    if executor is not None:
        pending = await executor.rebind(agent, engine_adapter)
        executor.update_agent_card(runtime_agent_card)
    set_a2a_agent_card_ctx(app, runtime_agent_card)
    return pending


def _validated_engine_adapter(
    agent: "Agent", startup: A2AServerStartup
) -> "A2AEngineAdapter":
    """Check the loaded model against *startup* and build its engine adapter."""
    from rasa.core.a2a_server.engine_adapter import build_a2a_engine_adapter_for_startup

    processor = agent.processor
    if processor is None:
        raise RasaException("Cannot bind the A2A server: agent model is not loaded.")

    validate_a2a_server_engine_or_raise(
        bound_engine_version=startup.engine_version,
        loaded_engine_version=processor.engine_version,
    )
    engine_adapter = build_a2a_engine_adapter_for_startup(agent, startup)
    engine_adapter.validate_startup(startup.settings, processor)
    return engine_adapter
